css:
.rent-receipt { color: #17324d; font-family: Georgia, serif; max-width: 760px; margin: 0 auto; padding: 36px; }
.receipt-header { border-bottom: 3px solid #e57a44; display: flex; justify-content: space-between; gap: 24px; padding-bottom: 20px; }
.eyebrow, .receipt-number span, .receipt-meta span, .party-grid span, .amount-box span { color: #7b8b99; display: block; font-family: sans-serif; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; }
h1 { font-size: 34px; margin: 7px 0 0; }
.receipt-number { text-align: right; } .receipt-number strong { font-family: monospace; font-size: 15px; }
.receipt-meta, .party-grid { display: grid; gap: 16px; grid-template-columns: repeat(3, 1fr); margin-top: 28px; }
.receipt-meta strong, .party-grid strong { display: block; font-size: 15px; margin-top: 5px; }
.amount-box { background: #f6e7dc; border-left: 5px solid #e57a44; margin-top: 34px; padding: 20px 24px; }
.amount-box strong { display: block; font-size: 30px; margin-top: 5px; }
.footer-note { border-top: 1px solid #d9e0e5; color: #6b7782; font-family: sans-serif; font-size: 12px; margin-top: 36px; padding-top: 16px; }
